240.sql:
SELECT DISTINCT element
FROM atom
WHERE molecule_id = 'TR004';

267.sql:
SELECT DISTINCT bond_type
FROM bond
WHERE molecule_id BETWEEN 'TR000' AND 'TR050';

291.sql:
WITH m_carcinogenic AS (
    SELECT molecule_id
    FROM molecule
    WHERE label = '+'
)
SELECT COUNT(*) AS answer FROM m_carcinogenic;

307.sql:
WITH atom_info AS (
    SELECT element
    FROM atom
    WHERE molecule_id IN (
        SELECT molecule_id
        FROM bond
        WHERE bond_id = 'TR000_2_3'
    )
)
SELECT DISTINCT element FROM atom_info;

387.sql:
WITH ogw_cards AS (
    SELECT id, name, colors, colorIdentity
    FROM cards
    WHERE setCode = 'OGW'
)
SELECT name, colors FROM ogw_cards;

436.sql:
WITH card_ids AS (
    SELECT id
    FROM cards
    WHERE frameEffects = 'extendedart'
)
SELECT COUNT(id) AS total_cards, GROUP_CONCAT(id) AS card_ids FROM card_ids;

617.sql:
SELECT Text 
FROM comments 
WHERE CreationDate = '2010-07-19 19:37:33.0';

653.sql:
WITH p_final AS (
    SELECT OwnerDisplayName
    FROM posts
    WHERE Id = (SELECT Id FROM posts ORDER BY ViewCount DESC LIMIT 1)
)
SELECT * FROM p_final;

729.sql:
WITH valid_marvel_superheroes AS (
    SELECT id, height_cm
    FROM superhero
    WHERE publisher_id = (SELECT id FROM publisher WHERE publisher_name = 'Marvel Comics') AND height_cm > 0
)
SELECT AVG(height_cm) AS average_height FROM valid_marvel_superheroes;

1035.sql:
SELECT team_fifa_api_id 
FROM Team_Attributes 
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

1393.sql:
WITH secretary_info AS (
    SELECT first_name, last_name, email
    FROM member
    WHERE position = 'Secretary'
)
SELECT first_name, last_name, email FROM secretary_info;

1411.sql:
SELECT expense_description 
FROM expense 
WHERE link_to_member = (SELECT member_id FROM member WHERE first_name = 'Sacha' AND last_name = 'Harrison');

1415.sql:
SELECT position FROM member AS m
INNER JOIN major AS mj ON m.link_to_major = mj.major_id
WHERE mj.major_name = 'Business';
